 h1{font-family:"Noto Serif SC","Source Han Serif SC","SimSun",serif;font-size:32px;font-weight:500;line-height:1.4;letter-spacing:-.6px;margin:5px 0}.comp-heading p{color:var(--muted);margin:0;font-size:12px}.snapshot-note{color:var(--faint);font-size:10px;text-align:right;border-left:1px solid #ffffff0f;padding-left:18px}.snapshot-note span{display:block;color:var(--muted);margin-top:4px;font-variant-numeric:tabular-nums}.source-tabs{display:flex;gap:6px;padding:4px;background:var(--surface-inset);border:1px solid #ffffff0a;border-radius:9px;width:fit-content;max-width:100%}.source-tabs button{font-size:12px;background:transparent;border:1px solid transparent;padding:7px 13px;border-radius:6px;color:var(--muted);white-space:nowrap}.source-tabs button.chosen{color:var(--text);background:#bcb8ac12;border-color:#bcb8ac18;box-shadow:0 1px 4px #0002}.source-tabs small{font-size:10px;margin-left:5px;opacity:.65}.tier-filters{display:flex;gap:5px;align-items:center;padding:19px 0 14px}.tier-filters>span{font-size:11px;color:var(--muted);margin-right:auto}.tier-filters button{background:none;border:1px solid transparent;font-size:11px;padding:3px 8px;color:var(--muted);border-radius:5px}.tier-filters .chosen{color:var(--text);background:#bcb8ac0e;border-color:#bcb8ac12}.comp-cards{display:flex;flex-direction:column;gap:12px;padding-bottom:20px}.comp-card{position:relative;isolation:isolate;overflow:hidden;border:1px solid #ffffff0d;background:var(--surface);border-radius:7px;flex-shrink:0;transition:border-color .15s}.comp-card:hover{border-color:#ffffff22}.comp-card.expanded{border-color:#bcb8ac27;background:var(--surface)}.comp-card.selected{border-color:#d49a7d90}.comp-art{position:absolute;width:60%;height:100%;right:0;top:0;object-fit:cover;object-position:80% 25%;opacity:.045;z-index:-1;mask-image:linear-gradient(90deg,transparent,#000 85%)}.comp-summary{width:100%;display:flex;align-items:center;text-align:left;gap:14px;border:0;background:transparent;padding:18px 