p:19px;padding:0 20px 23px}.comp-expanded h3{font-size:11px;font-weight:500;margin:20px 0 12px;color:var(--text)}.comp-expanded h3 small{font-size:10px;color:var(--muted);margin-left:6px;font-weight:400}.unit-strip{display:flex;gap:5px;flex-wrap:wrap}.unit-strip .portrait{height:28px;width:28px}.muted{font-size:11px;color:var(--muted)}.build-row{display:flex;gap:4px;align-items:center;margin:9px 0}.build-row span{font-size:11px;color:var(--muted);min-width:45px}.build-row img{width:22px;height:22px;border:1px solid #66665e;border-radius:3px}.trait-chips{display:flex;flex-wrap:wrap;gap:6px 4px}.trait-chips>span{font-size:10px;display:flex;align-items:center;gap:4px;padding:3px 5px;background:#bcb8ac0b;border:1px solid #bcb8ac10;border-radius:4px;color:var(--muted)}.trait-chips img{width:15px;height:15px;object-fit:contain}.trait-chips b{color:var(--text);font-size:10px}.level-steps{display:flex;flex-wrap:wrap;gap:5px}.level-steps span{font-size:10px;color:var(--muted);border:1px solid #ffffff0b;border-radius:4px;padding:4px 7px}.level-steps b{display:block;color:var(--text);font-size:11px;font-weight:500}.comp-stats{display:none}.mini-board{padding:4px 0}.hex-row{display:flex;gap:3px;height:29px}.hex-row:nth-child(even){padding-left:16px}.hex{width:29px;height:33px;padding:2px;border:0;border-radius:0;background:#343431;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%)}.hex.empty{opacity:.45;cursor:default}.hex img{width:100%;height:100%;object-fit:cover;clip-path:inherit}.empty-comps{padding:50px 15px;text-align:center;color:var(--muted)}.empty-comps h3{color:var(--text)}.empty-comps p{font-size:13px}
@media(max-width:1360px){.comp-browser{grid-template-columns:180px minmax(0,1fr);gap:20px}.catalog-grid{gap:11px 7px}.comp-title{width:150px}.comp-expanded{grid-template-columns:1fr 237px;gap:16px}.position-section{grid-column:2;grid-row:1 / span 2}.traits-section{grid-column:1}.summary-units{gap:6px}.summary-units .portrait{width:29px;height:29px}.comp-summary{gap:10px;padding-left:16px;padding-right:16px}.comp-pick{padding-left:16px;padding-right:16px}}
@media(max-width:1120px){.comp-browser{grid-template-columns:160px minmax(0,1fr);gap:16px}.catalog-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:10px 7px}.comp-title{width:135px}.summary-units .portrait{width:27px;height:27px}.source-tabs button{padding:6px 10px}}
</style>
